referenceSolutions.python:
def tallerKeycapsThresholdFile(readings, k):
    a=readings
    out=[]
    out=[0]*len(a)
    stack=[]
    for i,x in enumerate(a):
        while stack and a[stack[-1]]<x:
            j=stack.pop()
            out[j]=i-j
        stack.append(i)
    return sum(x>=k for x in out)

